import React, { useEffect, useState } from "react";
import Swal from "sweetalert2";
import { Lock, Pencil, Plus, ShieldCheck, Trash2, Users } from "lucide-react";
import { DashboardLayout } from "../components/layout/DashboardLayout";
import { RoleFormModal } from "../components/roles/RoleFormModal";
import { Button } from "../components/ui/button";
import { useAuth } from "../contexts/AuthContext";
import roleService from "../services/role.service";

export const RolesPage = () => {
  const { hasPermission } = useAuth();
  const canManage = hasPermission("roles.manage");

  const [roles, setRoles] = useState([]);
  const [permissions, setPermissions] = useState([]);
  const [loading, setLoading] = useState(true);
  const [modalOpen, setModalOpen] = useState(false);
  const [editingRole, setEditingRole] = useState(null);

  const loadData = async () => {
    setLoading(true);
    try {
      const [rolesData, permissionsData] = await Promise.all([
        roleService.getRoles(),
        roleService.getPermissions(),
      ]);
      setRoles(rolesData);
      setPermissions(permissionsData);
    } catch (error) {
      Swal.fire({
        icon: "error",
        title: "No se pudieron cargar los roles",
        text: error.response?.data?.detail || "Intenta nuevamente",
        confirmButtonColor: "#16a34a",
      });
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadData();
  }, []);

  const openCreateModal = () => {
    setEditingRole(null);
    setModalOpen(true);
  };

  const openEditModal = (role) => {
    setEditingRole(role);
    setModalOpen(true);
  };

  const handleDelete = async (role) => {
    const result = await Swal.fire({
      icon: "warning",
      title: `¿Eliminar el rol "${role.name}"?`,
      text: "Esta acción no se puede deshacer.",
      showCancelButton: true,
      confirmButtonText: "Eliminar",
      cancelButtonText: "Cancelar",
      confirmButtonColor: "#dc2626",
    });

    if (!result.isConfirmed) return;

    try {
      await roleService.deleteRole(role.id);
      await loadData();
    } catch (error) {
      Swal.fire({
        icon: "error",
        title: "No se pudo eliminar el rol",
        text: error.response?.data?.detail || "Intenta nuevamente",
        confirmButtonColor: "#16a34a",
      });
    }
  };

  return (
    <DashboardLayout>
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4 mb-6">
        <div>
          <h2 className="text-xl sm:text-2xl font-bold text-gray-900">
            Roles y Permisos
          </h2>
          <p className="text-sm text-gray-600 mt-1">
            Crea roles y define exactamente a qué módulos y acciones tienen
            acceso.
          </p>
        </div>

        {canManage && (
          <Button
            onClick={openCreateModal}
            className="bg-green-600 hover:bg-green-700 text-white"
          >
            <Plus className="w-4 h-4 mr-2" />
            Nuevo Rol
          </Button>
        )}
      </div>

      {loading ? (
        <div className="flex justify-center py-16">
          <div className="animate-spin rounded-full h-10 w-10 border-b-2 border-green-600" />
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {roles.map((role) => (
            <div
              key={role.id}
              className="bg-white rounded-xl shadow-sm border border-gray-100 p-5 flex flex-col"
            >
              <div className="flex items-start justify-between gap-2 mb-2">
                <div className="flex items-center gap-2">
                  <div className="p-2 rounded-lg bg-green-100">
                    <ShieldCheck className="w-5 h-5 text-green-600" />
                  </div>
                  <div>
                    <h3 className="font-bold text-gray-900 leading-tight">
                      {role.name}
                    </h3>
                    {role.is_system && (
                      <span className="inline-flex items-center gap-1 text-[10px] uppercase tracking-wide text-amber-600 font-semibold">
                        <Lock className="w-3 h-3" /> Rol de sistema
                      </span>
                    )}
                  </div>
                </div>
              </div>

              {role.description && (
                <p className="text-sm text-gray-500 mb-3">{role.description}</p>
              )}

              <div className="flex items-center gap-2 text-xs text-gray-500 mb-3">
                <Users className="w-3.5 h-3.5" />
                {role.is_company_scoped
                  ? "Ve solo empresas asignadas"
                  : "Ve todas las empresas"}
              </div>

              <div className="flex flex-wrap gap-1.5 mb-4">
                {role.permissions.length === 0 ? (
                  <span className="text-xs text-gray-400">Sin permisos asignados</span>
                ) : (
                  role.permissions.slice(0, 6).map((p) => (
                    <span
                      key={p.id}
                      className="text-[11px] bg-gray-100 text-gray-600 px-2 py-0.5 rounded-full"
                    >
                      {p.code}
                    </span>
                  ))
                )}
                {role.permissions.length > 6 && (
                  <span className="text-[11px] bg-gray-100 text-gray-600 px-2 py-0.5 rounded-full">
                    +{role.permissions.length - 6} más
                  </span>
                )}
              </div>

              {canManage && (
                <div className="mt-auto flex gap-2 pt-2 border-t border-gray-100">
                  <Button
                    variant="outline"
                    onClick={() => openEditModal(role)}
                    className="flex-1"
                  >
                    <Pencil className="w-4 h-4 mr-1.5" />
                    Editar
                  </Button>
                  {!role.is_system && (
                    <button
                      onClick={() => handleDelete(role)}
                      className="px-3 rounded-lg border border-gray-200 text-red-500 hover:bg-red-50 transition-colors"
                      aria-label={`Eliminar rol ${role.name}`}
                    >
                      <Trash2 className="w-4 h-4" />
                    </button>
                  )}
                </div>
              )}
            </div>
          ))}
        </div>
      )}

      <RoleFormModal
        open={modalOpen}
        onClose={() => setModalOpen(false)}
        role={editingRole}
        permissions={permissions}
        onSaved={loadData}
      />
    </DashboardLayout>
  );
};

export default RolesPage;
